"""Shared native/OCR/visual facts for Chat admission and on-demand reads."""

import json
import re
from pathlib import PurePath

from ..storage import get_storage
from .document_sources import ocr_records


def manifest(file):
    key = (file.meta or {}).get("document_manifest_key")
    return json.loads(get_storage().get_bytes(key)) if key else None


def native_text(file, unit, data):
    text = data.decode("utf-8")
    if unit.get("quality") == "no_text":
        return ""
    # Compatibility with ailab1: this exact wrapper was generated by our parser,
    # never supplied as native PDF text. New caches use structured content facts.
    if (
        data
        and (file.meta.get("extract") or {}).get("parser") == "zcode-3c5b227-ailab1"
        and re.fullmatch(r"## Page \d+\n\(no extractable text; the page may be scanned\)", text.strip())
    ):
        return ""
    return text


def unit_text(db, file, unit, native, records=None):
    text = native_text(file, unit, native)
    page = unit["unit_number"] - 1
    records = records if records is not None else ocr_records(db, file, [page])
    record = records.get(str(page)) if unit["anchor"].startswith("page:") else None
    if not text.strip() and record:
        return get_storage().get_bytes(record["text_key"]).decode("utf-8"), "ocr"
    return text, "native"


def visual_info(file, doc=None):
    doc = doc if doc is not None else manifest(file)
    if not doc:
        image = file.content_type.startswith("image/")
        office = PurePath(file.filename).suffix.lower() in {
            ".pdf",
            ".docx",
            ".doc",
            ".pptx",
            ".ppt",
            ".xlsx",
            ".xls",
            ".odt",
            ".odp",
            ".ods",
        }
        return {"status": "present" if image else "unknown" if office else "none", "units": []}
    units = doc.get("visual_units")
    if units is None:
        return {"status": "unknown", "units": []}
    return {"status": "present" if units else "none", "units": units[:200], "truncated": len(units) > 200}


def visual_pages(file, doc=None):
    doc = doc if doc is not None else manifest(file)
    info = visual_info(file, doc)
    if info["status"] == "none":
        return []
    # PDF pages/PPT slides have stable physical locations. Word and workbook
    # anchors do not map to rendered pages; rendering must establish that map.
    if doc and doc["kind"] in {"pdf", "pptx"}:
        return sorted({u["unit_number"] for u in info["units"]}) if info["status"] == "present" else list(range(1, doc["total_units"] + 1))
    return None
